import java.util.Scanner;

public class CreditCardValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a credit card number: ");
        String input = scanner.nextLine();

        // Remove any spaces or dashes from the input
        String cleanedInput = input.replaceAll("[\\s-]", "");

        if (cleanedInput.isEmpty()) {
            System.out.println("Error: Input cannot be empty.");
            return;
        }

        if (isValidLuhn(cleanedInput)) {
            System.out.println("The credit card number is valid.");
        } else {
            System.out.println("The credit card number is invalid.");
        }

        scanner.close();
    }

    /**
     * Validates a credit card number using Luhn's algorithm.
     * 
     * @param cardNumber The string representation of the credit card number.
     * @return true if the number is valid, false otherwise.
     */
    public static boolean isValidLuhn(String cardNumber) {
        int sum = 0;
        boolean isSecondToLast = true;

        // Iterate from right to left
        for (int i = cardNumber.length() - 1; i >= 0; i--) {
            char ch = cardNumber.charAt(i);

            // Check if the character is a digit
            if (!Character.isDigit(ch)) {
                return false;
            }

            int digit = Character.getNumericValue(ch);

            // Double every second digit from the right
            if (isSecondToLast) {
                digit *= 2;
                // If the result is greater than 9, subtract 9 (or sum the digits)
                if (digit > 9) {
                    digit -= 9;
                }
            }

            sum += digit;
            isSecondToLast = !isSecondToLast;
        }

        // The number is valid if the sum modulo 10 is 0
        return (sum % 10) == 0;
    }
}
